"use client";

import { useState } from "react";
import VegFilter from "../../../components/menu/VegFilter";
import { Restaurant } from "../../../data/types";
import CategoryTabs from "../../../components/menu/CategoryTabs";

type MenuClientProps = {
  restaurant: Restaurant;
};

export default function MenuClient({ restaurant }: MenuClientProps) {
  const [filter, setFilter] = useState<
    "all" | "veg" | "nonveg"
  >("all");

  return (
    <div className="min-h-screen p-4">
      <h1 className="text-xl font-bold mb-1">
        {restaurant.name}
      </h1>

      {restaurant.pure_veg && (
        <div className="text-green-600 mb-3">
          🟢 Pure Veg
        </div>
      )}

      <VegFilter value={filter} onChange={setFilter} />

      {restaurant.categories.map((cat) => {
        const visibleProducts = cat.products.filter(
          (item) =>
            filter === "all" ||
            (filter === "veg" && item.veg) ||
            (filter === "nonveg" && !item.veg)
        );

        if (visibleProducts.length === 0) return null;

        return (
          <div key={cat.id} className="mt-6">
            <h2 className="text-lg font-semibold mb-2">
              {cat.name}
            </h2>

            {visibleProducts.map((item) => (
              <div
                key={item.id}
                className="border-b py-3 flex justify-between"
              >
                <div>
                  <div className="font-medium">
                    {item.veg ? "🟢" : "🔴"} {item.name}
                  </div>

                  {!item.available && (
                    <div className="text-xs text-red-500">
                      Sold Out
                    </div>
                  )}

                  {item.description && (
                    <div className="text-sm text-gray-500">
                      {item.description}
                    </div>
                  )}
                </div>

                <div className="text-right text-sm">
                  {item.sizes.map((s) => (
                    <div key={s.id}>
                      {s.size_label} ₹{s.price}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        );
      })}
    </div>
  );
}
