"use client";

type VegFilterProps = {
  value: "all" | "veg" | "nonveg";
  onChange: (v: "all" | "veg" | "nonveg") => void;
};

export default function VegFilter({ value, onChange }: VegFilterProps) {
  return (
    <div className="flex gap-2 mb-4">
      <button
        onClick={() => onChange("all")}
        className={`flex-1 py-2 rounded-full text-sm ${
          value === "all"
            ? "bg-black text-white"
            : "border text-gray-700"
        }`}
      >
        All
      </button>

      <button
        onClick={() => onChange("veg")}
        className={`flex-1 py-2 rounded-full text-sm ${
          value === "veg"
            ? "bg-green-600 text-white"
            : "border text-green-700"
        }`}
      >
        🟢 Veg
      </button>

      <button
        onClick={() => onChange("nonveg")}
        className={`flex-1 py-2 rounded-full text-sm ${
          value === "nonveg"
            ? "bg-red-600 text-white"
            : "border text-red-700"
        }`}
      >
        🔴 Non-Veg
      </button>
    </div>
  );
}
